// Stand-in for the Rust WASM package (src/wasm/, generated by core/build-wasm.sh).
// Used by unit tests and by `VITE_USE_STUB=1` builds when wasm32 tooling is unavailable.
// Layout is a tiny JS spring layout; planning/ranking return empty results.
export default async function init() {}

export class WasmLayout {
  constructor(graphJson, seed) {
    const g = JSON.parse(graphJson);
    const n = g.tables.length;
    let s = (seed * 2654435761) >>> 0 || 1;
    const rnd = () => ((s ^= s << 13), (s ^= s >>> 17), (s ^= s << 5), ((s >>> 0) / 4294967296));
    this.pos = new Float32Array(n * 3).map(() => (rnd() * 2 - 1) * 60);
    const idx = new Map(g.tables.map((t, i) => [t.name, i]));
    this.edges = g.fks.map((f) => [idx.get(f.from.table), idx.get(f.to.table)]).filter(([a, b]) => a !== undefined && b !== undefined && a !== b);
    this.alpha = 1;
  }
  step(k) {
    const n = this.pos.length / 3;
    for (let it = 0; it < k && this.alpha > 0.01; it++, this.alpha *= 0.97) {
      const f = new Float32Array(n * 3);
      for (let a = 0; a < n; a++)
        for (let b = a + 1; b < n; b++) {
          const d = [0, 1, 2].map((c) => this.pos[a * 3 + c] - this.pos[b * 3 + c]);
          const r2 = d[0] ** 2 + d[1] ** 2 + d[2] ** 2 + 1;
          for (let c = 0; c < 3; c++) { f[a * 3 + c] += (d[c] / r2) * 400; f[b * 3 + c] -= (d[c] / r2) * 400; }
        }
      for (const [a, b] of this.edges)
        for (let c = 0; c < 3; c++) { const d = this.pos[b * 3 + c] - this.pos[a * 3 + c]; f[a * 3 + c] += d * 0.05; f[b * 3 + c] -= d * 0.05; }
      for (let i = 0; i < n * 3; i++) this.pos[i] += Math.max(-8, Math.min(8, (f[i] - this.pos[i] * 0.01) * this.alpha));
    }
  }
  positions() { return new Float32Array(this.pos); }
  settled() { return this.alpha <= 0.01; }
}
export const plan_candidates = () => "[]";
export const diagnose = () => "[]";
export const rank = () => "[]";
export const rank_flags = () => "[]";
